import pandas as pd
df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')

edges = {}
for idx, row in df.iterrows():
    edges[row['patient_id']] = row['emergency_contact_patient_id']

visited = set()
cycles = []

for node in edges:
    if node not in visited:
        path = []
        curr = node
        while curr not in visited:
            visited.add(curr)
            path.append(curr)
            curr = edges.get(curr, None)
            if curr is None:
                break
        if curr in path:
            cycle = path[path.index(curr):]
            cycles.append(cycle)

print("Cycles:")
for c in cycles:
    print(len(c), c)
EOF
python3 /app/analyze.py

