cat << 'EOF' > /app/analyze.py
import pandas as pd
df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')
edges = {row['patient_id']: row['emergency_contact_patient_id'] for idx, row in df.iterrows()}

cycle = {'PAT_065', 'PAT_080', 'PAT_178'}

def ends_at(start):
    curr = start
    while curr not in cycle:
        curr = edges[curr]
    return curr

counts = {'PAT_065': 0, 'PAT_080': 0, 'PAT_178': 0}
for p in edges:
    if p not in cycle:
        counts[ends_at(p)] += 1

print(counts)
EOF
